按简洁手写风格看看下面这个 TS EventBus 是否需要换一种封装。不要改行为，尤其是回调身份、取消订阅和链式返回；不改代码，只简短说明。

class EventBus {
  private events = new Map<string, (() => void)[]>()

  on(key: string, func: () => void) {
    if (!this.events.has(key)) this.events.set(key, [])
    this.events.get(key)!.push(func)
    return this
  }

  emit(key: string) {
    this.events.get(key)?.forEach((func) => func())
    return this
  }

  off(key: string, func: () => void) {
    const funcs = this.events.get(key)
    if (funcs) this.events.set(key, funcs.filter((f) => f !== func))
    return this
  }
}
